from solution import Entry, Report, solve

assert solve([], 0) == Report(0, 0, 0), 'fixture 0'
assert solve([], 5) == Report(0, 0, 0), 'fixture 1'
assert solve([], 1) == Report(0, 0, 0), 'fixture 2'
assert solve([Entry(3, 2, 1)], 2) == Report(0, 0, 0), 'fixture 3'
assert solve([Entry(4, 2, 4), Entry(4, 2, (-2))], 3) == Report(0, 0, 0), 'fixture 4'
assert solve([Entry(0, 1, 8), Entry(0, 0, 6), Entry(3, 1, 3)], 4) == Report(3, 6, 0), 'fixture 5'
assert solve([Entry(2, 2, 7), Entry(1, 3, (-1)), Entry(1, 3, 3), Entry(0, 2, 9)], 5) == Report(0, 0, 0), 'fixture 6'
assert solve([Entry(1, 3, (-2)), Entry(1, 2, (-1)), Entry(3, 1, (-1)), Entry(4, 3, 9), Entry(4, 2, 5)], 6) == Report(0, 0, 0), 'fixture 7'
assert solve([Entry(0, 3, 7), Entry(4, 1, 6), Entry(0, 1, 2), Entry(0, 3, 0), Entry(0, 0, 9), Entry(3, 3, 8)], 7) == Report(6, 9, 0), 'fixture 8'
assert solve([Entry(3, 0, 6), Entry(3, 1, 3), Entry(0, 0, 2), Entry(1, 3, 0), Entry(0, 3, (-1)), Entry(2, 1, 4), Entry(0, 3, 7)], 8) == Report(7, 0, 0), 'fixture 9'
assert solve([Entry(2, 3, 0), Entry(0, 2, 1), Entry(2, 1, 7), Entry(2, 1, 4), Entry(2, 1, 2), Entry(2, 2, 5), Entry(1, 0, 3), Entry(0, 3, (-2))], 1) == Report(0, 3, 0), 'fixture 10'
assert solve([Entry(3, 2, 1), Entry(0, 0, 5), Entry(0, 0, 0), Entry(4, 0, (-1)), Entry(1, 2, 4), Entry(4, 2, 9), Entry(0, 2, 2), Entry(4, 2, 3), Entry(1, 1, (-1))], 2) == Report(0, 0, 0), 'fixture 11'
assert solve([Entry(2, 1, 3), Entry(4, 2, 6), Entry(3, 3, (-2)), Entry(1, 3, 5), Entry(1, 0, 2), Entry(0, 3, 1), Entry(1, 1, 7), Entry(4, 1, 1), Entry(3, 1, 0), Entry(1, 3, 5)], 3) == Report(4, 0, 1), 'fixture 12'
assert solve([Entry(2, 2, 2), Entry(2, 1, 1), Entry(4, 0, 3), Entry(1, 1, 2), Entry(1, 1, 7), Entry(0, 1, (-1)), Entry(3, 3, (-2)), Entry(3, 3, 0), Entry(4, 0, 5), Entry(0, 3, 4), Entry(2, 0, 0)], 4) == Report(7, 5, 1), 'fixture 13'
assert solve([Entry(3, 0, 4), Entry(3, 1, 3), Entry(0, 1, 5), Entry(3, 2, (-2)), Entry(3, 1, 1), Entry(2, 2, 6), Entry(3, 0, 2), Entry(2, 1, (-2)), Entry(0, 3, 4), Entry(2, 2, 8), Entry(3, 0, 6), Entry(0, 0, 3)], 5) == Report(0, 9, 0), 'fixture 14'
assert solve([], 6) == Report(0, 0, 0), 'fixture 15'
assert solve([Entry(3, 0, 1)], 7) == Report(0, 1, 0), 'fixture 16'
assert solve([Entry(3, 2, 2), Entry(0, 1, 7)], 8) == Report(7, 0, 0), 'fixture 17'
assert solve([Entry(4, 0, 1), Entry(4, 1, 1), Entry(1, 2, (-2))], 1) == Report(1, 0, 1), 'fixture 18'
assert solve([Entry(4, 1, 5), Entry(4, 0, 6), Entry(1, 0, 8), Entry(0, 0, 5)], 2) == Report(0, 19, 0), 'fixture 19'
assert solve([Entry(2, 0, 0), Entry(1, 0, 3), Entry(1, 1, (-1)), Entry(2, 1, 0), Entry(1, 2, 2)], 3) == Report(0, 0, 0), 'fixture 20'
assert solve([Entry(4, 3, (-2)), Entry(1, 3, 6), Entry(3, 0, 2), Entry(4, 1, (-2)), Entry(4, 3, (-2)), Entry(3, 0, 0)], 4) == Report(0, 0, 0), 'fixture 21'
assert solve([Entry(1, 0, 5), Entry(3, 2, (-1)), Entry(3, 3, 5), Entry(0, 3, (-2)), Entry(4, 1, (-1)), Entry(1, 0, 3), Entry(2, 3, (-1))], 5) == Report(0, 3, 0), 'fixture 22'
assert solve([Entry(2, 3, (-1)), Entry(2, 0, (-1)), Entry(2, 2, 5), Entry(1, 3, 3), Entry(4, 2, 6), Entry(3, 0, 1), Entry(3, 0, 1), Entry(3, 0, 9)], 6) == Report(0, 9, 0), 'fixture 23'
assert solve([Entry(0, 1, 5), Entry(0, 1, 0)], 1) == Report(0, 0, 0), 'fixture 24'
assert solve([Entry(0, 1, 3), Entry(1, 0, 3)], 3) == Report(3, 3, 0), 'fixture 25'
assert solve([Entry(0, 1, 3)], 3) == Report(3, 0, 1), 'fixture 26'
assert solve([Entry(1, 1, 5), Entry(2, 0, 3), Entry(1, 2, 9), Entry(3, 1, 4)], 4) == Report(4, 3, 1), 'fixture 27'
